import{_ as d,a0 as r,w as l,s,ao as i,I as a,x as o,a1 as p,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"安卓編年史（8）：Android 1.5 Cupcake——虛擬鍵盤打開設備設計的大門 | LCTT x X-CMD","titleTemplate":false,"description":"安卓編年史（8）：Android 1.5 Cupcake——虛擬鍵盤打開設備設計的大門 | LCTT (The history of Android) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"安卓編年史（8）：Android 1.5 Cupcake——虛擬鍵盤打開設備設計的大門 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"安卓編年史（8）：Android 1.5 Cupcake——虛擬鍵盤打開設備設計的大門 | LCTT (The history of Android) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The history of Android/08 - The history of Android","title":"安卓編年史（8）：Android 1.5 Cupcake——虛擬鍵盤打開設備設計的大門","tag":"The history of Android","desc":""},"relativePath":"The history of Android/08 - The history of Android.md","filePath":"[post].md"}'),m={name:"The history of Android/08 - The history of Android.md"};function u(T,t,g,h,A,c){const e=r("Link");return l(),s("div",null,[t[20]||(t[20]=i('<h1 id="安卓編年史-8-android-1-5-cupcake——虛擬鍵盤打開設備設計的大門" tabindex="-1">安卓編年史（8）：Android 1.5 Cupcake——虛擬鍵盤打開設備設計的大門 <a class="header-anchor" href="#安卓編年史-8-android-1-5-cupcake——虛擬鍵盤打開設備設計的大門" aria-label="Permalink to “安卓編年史（8）：Android 1.5 Cupcake——虛擬鍵盤打開設備設計的大門”">​</a></h1><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2013/12/kb5.png" alt="安卓 1.5 的屏幕軟鍵盤輸入時的輸入建議欄，大寫狀態鍵盤，數字與符號界面，更多符號彈窗。"></p><p><em>安卓 1.5 的虛擬鍵盤輸入時的輸入建議欄、大寫狀態鍵盤、數字與符號界面、更多符號彈窗。 [Ron Amadeo 供圖]</em></p><h3 id="android-1-5-cupcake——虛擬鍵盤打開設備設計的大門" tabindex="-1">Android 1.5 Cupcake——虛擬鍵盤打開設備設計的大門 <a class="header-anchor" href="#android-1-5-cupcake——虛擬鍵盤打開設備設計的大門" aria-label="Permalink to “Android 1.5 Cupcake——虛擬鍵盤打開設備設計的大門”">​</a></h3><p>在 2009 年 4 月，安卓 1.1 發佈後將近三個月後，安卓 1.5 發佈了。這是第一個擁有公開的、市場化代號的安卓版本：紙杯蛋糕（Cupcake）。從這個版本開始，每個版本的安卓將會擁有一個按字母表排序，以小吃為主題的代號。</p><p>紙杯蛋糕新增功能中最重要的明顯當屬虛擬鍵盤。這是 OEM 廠商第一次有可能拋開帶有數不清的按鍵的實體鍵盤以及複雜的滑動結構，創造出平板風格的安卓設備。</p>',6)),a("p",null,[t[1]||(t[1]=o("安卓的按鍵標識可以在大小寫之間切換，這取決於大寫鎖定是否開啓。儘管默認情況下它是關閉的，顯示在鍵盤頂部的建議欄有個選項可以打開它。在按鍵的彈框中帶有省略號的，就像“u”，上面圖那樣的，可以在按住的情況下可以輸入彈框中的",-1)),p(e,{href:"http://en.wikipedia.org/wiki/Diacritic"},{default:n(()=>[...t[0]||(t[0]=[o("發音符號",-1)])]),_:1}),t[2]||(t[2]=o("。鍵盤可以切換到數字和符號，長按句號鍵可以打開更多符號。",-1))]),t[21]||(t[21]=i('<p><img src="http://cdn.arstechnica.net/wp-content/uploads/2013/12/abweave.png" alt="1.5和1.1中的應用程序界面和通知面板的對比。"></p><p><em>1.5 和 1.1 中的應用程序界面和通知面板的對比。 [Ron Amadeo 供圖]</em></p><p>給新的“攝像機”功能增加了新圖標，Google Talk 從 IM 中分離出來成為了一個獨立的應用。亞馬遜 MP3 和瀏覽器的圖標同樣經過了重新設計。亞馬遜 MP3 圖標更改的主要原因是亞馬遜即將計劃推出其它的安卓應用，而“A”圖標所指範圍太泛了。瀏覽器圖標無疑是安卓 1.1 中最糟糕的設計，所以它被重新設計了，並且不再像是一個桌面操作系統的對話框。應用抽屜的最後一個改變是“圖片”，它被重新命名為了“相冊”。</p><p>通知面板同樣經過了重新設計。面板背景加上了布紋紋理，通知的漸變效果也被平滑化了。安卓 1.5 在系統核心部分有許多設計上的微小改變，這些改變影響到所有的應用。在“清除通知”按鈕上，你可以看到全新的系統按鈕風格，與舊版本的按鈕相比有了漸變、更細的邊框線以及更少的陰影。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2013/12/widget.png" alt="安卓1.5和1.1中的“添加到主屏幕”對話框。"></p><p><em>安卓 1.5 和 1.1 中的“添加到主屏幕”對話框。 [Ron Amadeo 供圖]</em></p><p>第三方小部件是紙杯蛋糕的另一個頭等特性，它們現在仍然是安卓的本質特徵之一。無論是用來控制應用還是顯示應用的信息，開發者們都可以為他們的應用捆綁一個主屏幕小部件。谷歌同樣展示了一些它們自己的新的小部件，分別來自日曆和音樂這兩個應用。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2013/12/folders-and-widgets-and-stuff.png" alt="左：日曆小部件，音樂小部件以及一排實時文件夾的截圖。中：文件夾列表。右：“帶電話號碼的聯繫人”實時文件夾的打開視圖。"></p><p><em>左：日曆小部件，音樂小部件以及一排實時文件夾的截圖。中：文件夾列表。右：“帶電話號碼的聯繫人”實時文件夾的打開視圖。 [Ron Amadeo 供圖]</em></p><p>在上方左邊的截圖裏你可以看到新的日曆和音樂圖標。日曆小部件只能顯示當天的一個事件，點擊它會打開日曆。你不能夠選擇日曆所顯示的內容，小部件也不能夠重新設置大小——它就是上面看起來的那個樣子。音樂小部件是藍色的——儘管音樂應用裏沒有一丁點的藍色——它展示了歌曲名和歌手名，此外還有播放和下一曲按鈕。</p>',10)),a("p",null,[t[4]||(t[4]=o("同樣在左側截圖裏，底部一排的頭三個文件夾是一個叫做“",-1)),p(e,{href:"http://android-developers.blogspot.com/2009/04/live-folders.html"},{default:n(()=>[...t[3]||(t[3]=[o("實時文件夾",-1)])]),_:1}),t[5]||(t[5]=o("”的新特性。它們可以在“添加到主屏幕”菜單中的新頂層選項“文件夾”中被找到，就像你在中間那張圖看到的那樣。實時文件夾可以展示一個應用的內容而不用打開這個應用。紙杯蛋糕帶來的都是和聯繫人相關的實時文件夾，能夠顯示所有聯繫人，帶有電話號碼的聯繫人和加星標的聯繫人。",-1))]),t[22]||(t[22]=i('<p>實時文件夾在主屏的彈窗使用了一個簡單的列表視圖，而不是圖標。聯繫人只是實時文件夾的一個初級應用，它是給開發者使用的一個完整 API。谷歌用 Google Books 應用做了個圖書文件夾的演示，它可以顯示 RSS 訂閲或是一個網站的熱門故事。實時文件夾是安卓沒有成功實現的想法之一，這個特性最終在蜂巢（3.x）中被取消。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2013/12/device-2013-12-26-11016071.png" alt="攝像機和相機界面，屏幕上有觸摸快門。"></p><p><em>攝像機和相機界面，屏幕上有觸摸快門。 [Ron Amadeo 供圖]</em></p><p>如果你不能認出新的“攝像機”圖標，這不奇怪，視頻錄製是在安卓 1.5 中才被添加進來的。相機和攝像機兩個圖標其實是同一個應用，你可用過菜單中的“切換至相機”和“切換至攝像機”選項在它們之間切換。T-Mobile G1 上錄製的視頻質量並不高。一個“高”質量的測試視頻輸出一個 .3GP 格式的視頻文件，其分辨率僅為 352 x 288，幀率只有 4FPS。</p><p>除了新的視頻特性，相機應用中還可以看到一些急需的 UI 調整。上方左側的快照展示了最近拍攝的那張照片，點擊它會跳轉到相冊中的相機膠捲。各個界面上方右側的圓形圖標是觸摸快門，這意味着，從 1.5 開始，安卓設備不再需要一個實體相機按鈕。</p><p>這個界面相比於之後版本的相機應用實際上更加接近於安卓 4.2 的設計。儘管後續的設計會向相機加入愚蠢的皮革紋理和更多的控制設置，安卓最終還是回到了基本的設計，安卓 4.2 的重新設計和這裏有很多共同之處。安卓 1.5 中的原始佈局演變成了安卓 4.2 中的最小化的、全屏的取景器。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2013/12/gtalk-im.png" alt="Google Talk運行在Google Talk中vs運行在IM應用中。"></p><p><em>Google Talk 運行在 Google Talk 中 vs 運行在 IM 應用中。 [Ron Amadeo 供圖]</em></p><p>安卓 1.0 的 IM 即時通訊應用功能上支持 Google Talk，但在安卓 1.5 中，Google Talk 從中分離出來成為獨立應用。IM應用中對其的支持已經被移除。Google Talk（上圖左側）明顯是基於 IM 應用（上圖右側）的，但隨着獨立應用在 1.5 中的發佈，在 IM 應用的工作被放棄了。</p><p>新的 Google Talk 應用擁有重新設計過的狀態欄、右側狀態指示燈、重新設計過的移動設備標識，是個灰色的安卓小綠人圖案。聊天界面的藍色的輸入框變成了更加合理的灰色，消息的背景從淡綠和白色變成了淡綠和綠色。有了獨立的應用，谷歌可以向其中添加 Gtalk 獨有的特性，比如“不保存聊天記錄”聊天，該特性可以阻止 Gmail 保存每個聊天記錄。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2013/12/cal15.png" alt="安卓1.5的日曆更加明亮。"></p><p><em>安卓 1.5 的日曆更加明亮。 [Ron Amadeo 供圖]</em></p><p>日曆拋棄了醜陋的黑色背景上白色方塊的設計，轉變為全淺色主題。所有東西的背景都變成了白色，頂部的星期日變成了藍色。單獨的約會方塊從帶有顏色的細條變成了擁有整個顏色背景，文字也變為白色。這將是很長一段時間內日曆的最後一次改動。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2013/12/browser-craziness.png" alt="從左到右：新的瀏覽器控件，縮放視圖，複製/粘貼文本高亮。"></p><p><em>從左到右：新的瀏覽器控件，縮放視圖，複製/粘貼文本高亮。 [Ron Amadeo 供圖]</em></p><p>安卓 1.5 從系統全局修改了縮放控件。縮放控件不再是兩個大圓形，取而代之的是一個圓角的矩形從中間分開為左右兩個按鈕。這些新的控件被用在了瀏覽器、谷歌地圖和相冊之中。</p><p>瀏覽器在縮放功能上做了很多工作。在放大或縮小之後，點擊“1x”按鈕可以回到正常縮放狀態。底部右側的按鈕會將縮放整個頁面並在頁面上顯示一個放大矩形框，就像你能在上面中間截圖看到的那樣。按住矩形框並且釋放會將頁面的那一部分顯示回“1x”視圖。安卓並沒有加速滾動，這使得最快的滾動速度也着實很慢——這就是谷歌對長網頁頁面導航的解決方案。</p><p>瀏覽器的另一個新增功能就是從網頁上覆制文本——之前你只能從輸入框中複製文本。在菜單中選擇“複製文本”會激活高亮模式，在網頁文本上拖動你的手指使它們高亮。G1 的軌跡球對於這種精準的移動十分的方便，並且能夠控制鼠標指針。這裏並沒有可以拖動的光標，當你的手指離開屏幕的時候，安卓就會複製文本並且移除高亮。所以你必須做到荒謬般的精確來使用複製功能。</p><p>安卓 1.5 中的瀏覽器很容易崩潰——比之前的版本經常多了。僅僅是以桌面模式瀏覽 Ars Technica 就會導致崩潰，許多其它的站點也是一樣。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2013/12/lockscreen.png" alt=""></p><p><em>Ron Amadeo供圖</em></p><p>默認的鎖屏界面和圖形鎖屏都不再是空蕩蕩的黑色背景，而是和主屏幕一致的壁紙。</p><p>圖形解鎖界面的淺色背景顯示出了谷歌在圓圈對齊工作上的草率和馬虎。白色圓圈在黑圓圈裏從來都不是在正中心的位置——像這樣基本的對齊問題對於這一時期的安卓是個頻繁出現的問題。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2013/12/TWEAKS2.png" alt="Youtube上傳工具，內容快照，自動旋轉設置，全新的音樂應用設計。"></p><p><em>Youtube 上傳工具，內容快照，自動旋轉設置，全新的音樂應用設計。 [Ron Amadeo 供圖]</em></p><p>安卓 1.5 給予了 YouTube 應用向其網站上傳視頻的能力。上傳通過從相冊中分享視頻到 YouTube 應用來完成，或從 YouTube 應用中直接打開一個視頻。這將會打開一個上傳界面，用户在這裏可以設置像視頻標題、標籤和權限這樣的選項。照片可以以類似的方式上傳到 Picasa，這是一個谷歌建立的圖片網站。</p><p>整個系統的調整沒有多少。常用聯繫人在聯繫人列表中可以顯示圖片（儘管常規聯繫人還是沒有圖片）。第三張截圖展示了設置中全新的自動旋轉選項——這個版本同樣也是第一個支持基於從設備內部傳感器讀取的數據來自動切換方向的版本。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/04/htc-magic-white.jpg" alt="HTC Magic，第二部安卓設備，第一個不帶實體鍵盤的設備。"></p><p><em>HTC Magic，第二部安卓設備，第一個不帶實體鍵盤的設備。 [HTC 供圖]</em></p><p>紙杯蛋糕在改進安卓上做了巨大的工作，特別是從硬件方面。虛擬鍵盤意味着不再需要實體鍵盤。自動旋轉使得系統更加接近 iPhone，屏幕上的虛擬快門按鍵同樣也意味着實體相機按鍵變成了可選選項。1.5 發佈後不久，第二部安卓設備的出現將會展示出這個平台未來的方向：HTC Magic。Magic（上圖）沒有實體鍵盤或相機按鈕。它是沒有間隙、沒有滑動結構的平板狀設備，依賴於安卓的虛擬按鍵來完成任務。</p><p>安卓旗艦機開始可能有着最多按鍵——一個實體 qwerty 鍵盤——後來隨着時間流逝開始慢慢減少按鍵數量。而 Magic 是重大的一步，去除了整個鍵盤和相機按鈕，它仍然使用通話和掛斷鍵、四個系統鍵以及軌跡球。</p><h4 id="谷歌地圖是第一個登陸谷歌市場的內置應用" tabindex="-1">谷歌地圖是第一個登陸谷歌市場的內置應用 <a class="header-anchor" href="#谷歌地圖是第一個登陸谷歌市場的內置應用" aria-label="Permalink to “谷歌地圖是第一個登陸谷歌市場的內置應用”">​</a></h4><p>儘管這篇文章為了簡單起見，（主要）以安卓版本順序來組織應用更新，但還是有一些在這時間線之外的東西值得我們特別注意一下。2009 年 6 月 14 日，谷歌地圖成為第一個通過谷歌市場更新的預置應用。儘管其它的所有應用更新還是要在一個完整的系統發佈中進行更新，但是地圖從系統中脱離了出來，只要新特性已經就緒就可以隨時接收升級週期之外的更新。</p><p>將應用從核心系統分離發佈到安卓市場上將成為谷歌前進的主要關注點。總的來説，OTA 更新是個重大的主動改進——這需要 OEM 廠商和運營商的合作，二者都是拖後腿的角色。更新同樣沒有做到到達每個設備。今天，谷歌市場給了谷歌一個與每個安卓手機之間的聯繫渠道，而沒有了這樣的外界干擾。</p><p>然而，這是後來才需要考慮的問題。在 2009 年，谷歌只有兩種裸機需要支持，而且早期的安卓運營商似乎對谷歌的升級需要反應積極。這些早期的行動對谷歌這方面來説將被證明是非常積極的決定。一開始，公司只在最重要的應用——地圖和 Gmail 上——走這條路線，但後來它將大部分預置應用導入安卓市場。後來的舉措比如 Google Play 服務甚至將應用 API 從系統移除加入了谷歌商店。</p><p>至於這時的新地圖應用，得到了一個新的路線界面，此外還有提供公共交通和步行方向的能力。現在，路線只有個樸素的黑色列表界面——逐步風格的導航很快就會登場。</p><p>2009 年 6 月同時還是蘋果發佈第三代 iPhone——3GS——以及第三版 iPhone OS 的時候。iPhone OS 3 的主要特性大多是追趕上來的項目，比如複製/粘貼和對彩信的支持。蘋果的硬件依然是更好的，軟件更流暢、更整合，還有更好的設計。儘管谷歌瘋狂的開發步伐使得它不得不走上追趕的道路。iPhone OS 2 是在安卓 0.5 的 Milestone 5 版本之前發佈的，在 iOS 一年的發佈週期裏安卓發佈了五個版本。</p><hr><p><img src="http://cdn.arstechnica.net/wp-content//uploads/authors/ron-amadeo-sq.jpg" alt="Ron Amadeo"></p>',39)),a("p",null,[p(e,{href:"http://arstechnica.com/author/ronamadeo"},{default:n(()=>[...t[6]||(t[6]=[o("Ron Amadeo",-1)])]),_:1}),t[7]||(t[7]=o(" / Ron是Ars Technica的評論編緝，專注於安卓系統和谷歌產品。他總是在追尋新鮮事物，還喜歡拆解事物看看它們到底是怎麼運作的。",-1))]),a("p",null,[p(e,{href:"https://twitter.com/RonAmadeo"},{default:n(()=>[...t[8]||(t[8]=[o("@RonAmadeo",-1)])]),_:1})]),t[23]||(t[23]=a("hr",null,null,-1)),a("p",null,[t[10]||(t[10]=o("via: ",-1)),p(e,{href:"http://arstechnica.com/gadgets/2014/06/building-android-a-40000-word-history-of-googles-mobile-os/8/"},{default:n(()=>[...t[9]||(t[9]=[o("http://arstechnica.com/gadgets/2014/06/building-android-a-40000-word-history-of-googles-mobile-os/8/",-1)])]),_:1})]),a("p",null,[t[13]||(t[13]=o("譯者：",-1)),p(e,{href:"https://github.com/alim0x"},{default:n(()=>[...t[11]||(t[11]=[o("alim0x",-1)])]),_:1}),t[14]||(t[14]=o(" 校對：",-1)),p(e,{href:"https://github.com/wxy"},{default:n(()=>[...t[12]||(t[12]=[o("wxy",-1)])]),_:1})]),a("p",null,[t[17]||(t[17]=o("本文由 ",-1)),p(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[15]||(t[15]=[o("LCTT",-1)])]),_:1}),t[18]||(t[18]=o(" 原創翻譯，",-1)),p(e,{href:"http://linux.cn/"},{default:n(()=>[...t[16]||(t[16]=[o("Linux中國",-1)])]),_:1}),t[19]||(t[19]=o(" 榮譽推出",-1))])])}const w=d(m,[["render",u]]);export{C as __pageData,w as default};
